## Design Note

- **Tokenizer**: single-pass, produces a list of `(type, value, position)` tuples; `O(n)` time/space.
- **Parser**: iterative Pratt (operator-precedence) parser using an explicit frame stack — no recursion per nesting level; `O(n)` time.
- **AST**: immutable tuple trees (`('num',v)`, `('var',name)`, `('bin',op,l,r)`, `('un',op,x)`, `('fn',name,pos,args)`).
- **Evaluation**: iterative post-order traversal with an explicit (op-stack, value-stack) pair; `O(n)` per call, no recursion.
- **Concurrency**: `Expr` is immutable after construction; `evaluate` allocates only local stacks → inherently thread-safe.
- **Compile-time checks**: single iterative AST walk collects variables and validates function names/arity (leftmost error wins).

### solution.py
```python
"""Safe formula engine for spreadsheet cells – no eval/exec/ast."""

import math
from typing import Mapping

# ─── Exceptions ────────────────────────────────────────────────────────────────

class ExprError(Exception):
    """Base of every error."""

class ExprSyntaxError(ExprError):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.message = message
        self.position = position

class ExprNameError(ExprError):
    def __init__(self, name: str):
        super().__init__(f"unknown name '{name}'")
        self.name = name

class ExprEvalError(ExprError):
    pass

# ─── Function table ────────────────────────────────────────────────────────────

_FUNC_TABLE: dict[str, tuple[int, int | None]] = {
    'abs':   (1, 1),
    'sqrt':  (1, 1),
    'min':   (1, None),
    'max':   (1, None),
    'round': (1, 2),
    'if':    (3, 3),
}

# ─── Tokenizer ─────────────────────────────────────────────────────────────────

_DIGITS = frozenset('0123456789')
_LETTERS = frozenset('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')
_IDENT_START = _LETTERS | frozenset('_')
_IDENT_CHARS = _IDENT_START | _DIGITS

# Token type constants
_TOK_NUM    = 0
_TOK_IDENT  = 1
_TOK_OP     = 2
_TOK_LPAREN = 3
_TOK_RPAREN = 4
_TOK_COMMA  = 5
_TOK_EOF    = 6

# Operator precedence and associativity
_BIN_PREC: dict[str, int] = {
    '<': 1, '<=': 1, '>': 1, '>=': 1, '==': 1, '!=': 1,
    '+': 2, '-': 2,
    '*': 3, '/': 3, '%': 3,
    '^': 5,
}
_RIGHT_ASSOC = frozenset('^')
_NON_ASSOC = frozenset(('<=', '>=', '<', '>', '==', '!='))


def _tokenize(src: str) -> list[tuple[int, object, int]]:
    """Return list of (type, value, position). Raises ExprSyntaxError on bad input."""
    tokens: list[tuple[int, object, int]] = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        # whitespace
        if c == ' ' or c == '\t' or c == '\n' or c == '\r':
            i += 1
            continue
        # number
        if c in _DIGITS or (c == '.' and i + 1 < n and src[i + 1] in _DIGITS):
            start = i
            while i < n and src[i] in _DIGITS:
                i += 1
            if i < n and src[i] == '.':
                i += 1
                while i < n and src[i] in _DIGITS:
                    i += 1
            if i < n and (src[i] == 'e' or src[i] == 'E'):
                j = i + 1
                if j < n and (src[j] == '+' or src[j] == '-'):
                    j += 1
                if j < n and src[j] in _DIGITS:
                    i = j
                    while i < n and src[i] in _DIGITS:
                        i += 1
                else:
                    raise ExprSyntaxError("malformed number", start)
            text = src[start:i]
            val = float(text)
            if math.isinf(val):
                raise ExprSyntaxError("number too large", start)
            tokens.append((_TOK_NUM, val, start))
        # identifier
        elif c in _IDENT_START:
            start = i
            i += 1
            while i < n and src[i] in _IDENT_CHARS:
                i += 1
            tokens.append((_TOK_IDENT, src[start:i], start))
        # single/double-char operators and punctuation
        elif c == '(':
            tokens.append((_TOK_LPAREN, '(', i)); i += 1
        elif c == ')':
            tokens.append((_TOK_RPAREN, ')', i)); i += 1
        elif c == ',':
            tokens.append((_TOK_COMMA, ',', i)); i += 1
        elif c == '<':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append((_TOK_OP, '<=', i)); i += 2
            else:
                tokens.append((_TOK_OP, '<', i)); i += 1
        elif c == '>':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append((_TOK_OP, '>=', i)); i += 2
            else:
                tokens.append((_TOK_OP, '>', i)); i += 1
        elif c == '=':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append((_TOK_OP, '==', i)); i += 2
            else:
                raise ExprSyntaxError("invalid character '='", i)
        elif c == '!':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append((_TOK_OP, '!=', i)); i += 2
            else:
                raise ExprSyntaxError("invalid character '!'", i)
        elif c in '+-*/%^':
            tokens.append((_TOK_OP, c, i)); i += 1
        else:
            raise ExprSyntaxError(f"invalid character '{c}'", i)
    tokens.append((_TOK_EOF, '', n))
    return tokens

# ─── Iterative Pratt Parser ────────────────────────────────────────────────────

# Frame tags
_F_NEED_VALUE   = 0   # (tag, min_prec)
_F_NEED_PREFIX  = 1   # (tag,)
_F_UNARY        = 2   # (tag, op)
_F_INFIX        = 3   # (tag, min_prec, left_or_None)
_F_AFTER_BIN    = 4   # (tag, op, left, next_min_prec)
_F_PAREN        = 5   # (tag,)
_F_FUNC         = 6   # (tag, name, name_pos, args_tuple, min_n, max_n)
_F_FUNC_AFTER   = 7   # (tag, name, name_pos, args_tuple, min_n, max_n)


def _parse(tokens: list[tuple[int, object, int]]) -> tuple:
    """Iterative Pratt parser. Returns AST root tuple."""
    pos = 0
    stack: list[tuple] = [(_F_NEED_VALUE, 0)]
    result = None  # value "returned" by last completed sub-expression

    while stack:
        frame = stack.pop()
        tag = frame[0]

        if tag == _F_NEED_VALUE:
            min_prec = frame[1]
            stack.append((_F_INFIX, min_prec, None))
            stack.append((_F_NEED_PREFIX,))

        elif tag == _F_NEED_PREFIX:
            tt, tv, tp = tokens[pos]
            if tt == _TOK_OP and (tv == '+' or tv == '-'):
                stack.append((_F_UNARY, tv))
                stack.append((_F_NEED_VALUE, 5))
                pos += 1
            elif tt == _TOK_NUM:
                result = ('num', tv)
                pos += 1
            elif tt == _TOK_IDENT:
                ntt = tokens[pos + 1][0]
                if ntt == _TOK_LPAREN:
                    name = tv
                    name_pos = tp
                    min_n, max_n = _FUNC_TABLE.get(name, (0, None))
                    stack.append((_F_FUNC, name, name_pos, (), min_n, max_n))
                    pos += 2  # skip IDENT and '('
                else:
                    result = ('var', tv)
                    pos += 1
            elif tt == _TOK_LPAREN:
                stack.append((_F_PAREN,))
                stack.append((_F_NEED_VALUE, 0))
                pos += 1
            else:
                raise ExprSyntaxError("unexpected token", tp)

        elif tag == _F_UNARY:
            result = ('un', frame[1], result)

        elif tag == _F_INFIX:
            min_prec = frame[1]
            left = frame[2]
            if left is None:
                left = result
            tt, tv, tp = tokens[pos]
            if tt == _TOK_OP:
                prec = _BIN_PREC.get(tv)
                if prec is not None and prec >= min_prec:
                    op = tv
                    pos += 1
                    if op in _NON_ASSOC:
                        stack.append((_F_AFTER_BIN, op, left, prec + 1))
                        stack.append((_F_NEED_VALUE, prec + 1))
                    elif op in _RIGHT_ASSOC:
                        stack.append((_F_AFTER_BIN, op, left, min_prec))
                        stack.append((_F_NEED_VALUE, prec))
                    else:  # left-assoc
                        stack.append((_F_AFTER_BIN, op, left, min_prec))
                        stack.append((_F_NEED_VALUE, prec + 1))
                    continue
            # no binary op consumed → expression complete
            result = left

        elif tag == _F_AFTER_BIN:
            op, left, next_min = frame[1], frame[2], frame[3]
            right = result
            result = ('bin', op, left, right)
            stack.append((_F_INFIX, next_min, result))

        elif tag == _F_PAREN:
            tt, tv, tp = tokens[pos]
            if tt != _TOK_RPAREN:
                raise ExprSyntaxError("expected ')'", tp)
            pos += 1
            # result stays as the inner expression

        elif tag == _F_FUNC:
            name, name_pos, args, min_n, max_n = frame[1], frame[2], frame[3], frame[4], frame[5]
            tt, tv, tp = tokens[pos]
            if tt == _TOK_RPAREN:
                pos += 1
                result = ('fn', name, name_pos, args)
            else:
                stack.append((_F_FUNC_AFTER, name, name_pos, args, min_n, max_n))
                stack.append((_F_NEED_VALUE, 0))

        elif tag == _F_FUNC_AFTER:
            name, name_pos, args, min_n, max_n = frame[1], frame[2], frame[3], frame[4], frame[5]
            args = args + (result,)
            tt, tv, tp = tokens[pos]
            if tt == _TOK_COMMA:
                pos += 1
                stack.append((_F_FUNC, name, name_pos, args, min_n, max_n))
            elif tt == _TOK_RPAREN:
                pos += 1
                result = ('fn', name, name_pos, args)
            else:
                raise ExprSyntaxError("expected ',' or ')'", tp)

    # All tokens must be consumed
    if tokens[pos][0] != _TOK_EOF:
        raise ExprSyntaxError("unexpected token", tokens[pos][2])
    return result

# ─── AST Analysis (iterative) ─────────────────────────────────────────────────

def _analyze(root: tuple) -> frozenset[str]:
    """Collect variables; validate function names and arg counts (leftmost error wins)."""
    variables: set[str] = set()
    # (position, exception) pairs for function errors
    func_errors: list[tuple[int, Exception]] = []
    walk: list[tuple] = [root]

    while walk:
        node = walk.pop()
        t = node[0]
        if t == 'var':
            variables.add(node[1])
        elif t == 'fn':
            name, fpos, args = node[1], node[2], node[3]
            if name not in _FUNC_TABLE:
                func_errors.append((fpos, ExprNameError(name)))
            else:
                min_n, max_n = _FUNC_TABLE[name]
                n = len(args)
                if n < min_n or (max_n is not None and n > max_n):
                    func_errors.append((fpos, ExprSyntaxError(
                        f"wrong number of arguments for '{name}'", fpos)))
            for a in args:
                walk.append(a)
        elif t == 'bin':
            walk.append(node[2])
            walk.append(node[3])
        elif t == 'un':
            walk.append(node[2])

    if func_errors:
        func_errors.sort(key=lambda x: x[0])
        raise func_errors[0][1]
    return frozenset(variables)

# ─── Iterative Evaluator ───────────────────────────────────────────────────────

_S_EVAL      = 0  # (tag, node)
_S_VAL       = 1  # (tag, float_value)
_S_APPLY_BIN = 2  # (tag, op)
_S_APPLY_UN  = 3  # (tag, op)
_S_APPLY_FN  = 4  # (tag, name, nargs)
_S_IF_PICK   = 5  # (tag, then_node, else_node)

_FINITE = math.isfinite


def _do_binop(op: str, a: float, b: float) -> float:
    if op == '+':
        r = a + b
    elif op == '-':
        r = a - b
    elif op == '*':
        r = a * b
    elif op == '/':
        if b == 0.0:
            raise ExprEvalError("division by zero")
        r = a / b
    elif op == '%':
        if b == 0.0:
            raise ExprEvalError("modulo by zero")
        r = a % b
    elif op == '^':
        if a == 0.0 and b < 0.0:
            raise ExprEvalError("zero to negative power")
        if a < 0.0 and b != int(b):
            raise ExprEvalError("negative base with non-integer exponent")
        r = a ** b
    elif op == '<':
        return 1.0 if a < b else 0.0
    elif op == '<=':
        return 1.0 if a <= b else 0.0
    elif op == '>':
        return 1.0 if a > b else 0.0
    elif op == '>=':
        return 1.0 if a >= b else 0.0
    elif op == '==':
        return 1.0 if a == b else 0.0
    elif op == '!=':
        return 1.0 if a != b else 0.0
    else:
        raise ExprEvalError(f"unknown operator '{op}'")
    if not _FINITE(r):
        raise ExprEvalError("result is not finite")
    return r


def _do_unop(op: str, a: float) -> float:
    if op == '-':
        return -a
    return a  # '+'


def _do_func(name: str, args: list[float]) -> float:
    if name == 'abs':
        r = abs(args[0])
    elif name == 'sqrt':
        if args[0] < 0.0:
            raise ExprEvalError("sqrt of negative number")
        r = math.sqrt(args[0])
    elif name == 'min':
        r = min(args)
    elif name == 'max':
        r = max(args)
    elif name == 'round':
        x = args[0]
        if len(args) == 1:
            r = float(round(x))
        else:
            n = args[1]
            if n != int(n):
                raise ExprEvalError("round digits must be integer-valued")
            r = float(round(x, int(n)))
    else:
        raise ExprEvalError(f"unknown function '{name}'")
    if not _FINITE(r):
        raise ExprEvalError("result is not finite")
    return r


def _eval(root: tuple, variables: Mapping[str, float]) -> float:
    ops: list[tuple] = [(_S_EVAL, root)]
    vals: list[float] = []

    while ops:
        item = ops.pop()
        tag = item[0]

        if tag == _S_VAL:
            vals.append(item[1])

        elif tag == _S_EVAL:
            node = item[1]
            nt = node[0]
            if nt == 'num':
                vals.append(node[1])
            elif nt == 'var':
                name = node[1]
                try:
                    raw = variables[name]
                except KeyError:
                    raise ExprNameError(name) from None
                val = float(raw)
                if not _FINITE(val):
                    raise ExprEvalError(f"variable '{name}' is not finite")
                vals.append(val)
            elif nt == 'bin':
                ops.append((_S_APPLY_BIN, node[1]))
                ops.append((_S_EVAL, node[3]))
                ops.append((_S_EVAL, node[2]))
            elif nt == 'un':
                ops.append((_S_APPLY_UN, node[1]))
                ops.append((_S_EVAL, node[2]))
            elif nt == 'fn':
                fname = node[1]
                args = node[3]
                if fname == 'if':
                    ops.append((_S_IF_PICK, args[1], args[2]))
                    ops.append((_S_EVAL, args[0]))
                else:
                    nargs = len(args)
                    ops.append((_S_APPLY_FN, fname, nargs))
                    for i in range(nargs - 1, -1, -1):
                        ops.append((_S_EVAL, args[i]))

        elif tag == _S_APPLY_BIN:
            b = vals.pop()
            a = vals.pop()
            vals.append(_do_binop(item[1], a, b))

        elif tag == _S_APPLY_UN:
            a = vals.pop()
            vals.append(_do_unop(item[1], a))

        elif tag == _S_APPLY_FN:
            fname = item[1]
            nargs = item[2]
            args = [vals.pop() for _ in range(nargs)]
            args.reverse()
            vals.append(_do_func(fname, args))

        elif tag == _S_IF_PICK:
            cond = vals.pop()
            if cond != 0.0:
                ops.append((_S_EVAL, item[1]))
            else:
                ops.append((_S_EVAL, item[2]))

    return vals[0]

# ─── Expr class ────────────────────────────────────────────────────────────────

class Expr:
    __slots__ = ('source', 'variables', '_root')

    def __init__(self, source: str, root: tuple, variables: frozenset[str]):
        # Use object.__setattr__ for immutability via __slots__
        object.__setattr__(self, 'source', source)
        object.__setattr__(self, '_root', root)
        object.__setattr__(self, 'variables', variables)

    def __setattr__(self, name, value):
        raise AttributeError("Expr is immutable")

    def __delattr__(self, name):
        raise AttributeError("Expr is immutable")

    def evaluate(self, variables: Mapping[str, float] | None = None) -> float:
        if variables is None:
            variables = {}
        return _eval(self._root, variables)

# ─── Public API ────────────────────────────────────────────────────────────────

def compile_expr(src: str) -> Expr:
    if not isinstance(src, str):
        raise TypeError(f"expected str, got {type(src).__name__}")
    tokens = _tokenize(src)
    root = _parse(tokens)
    variables = _analyze(root)
    return Expr(src, root, variables)


def evaluate(src: str, variables: Mapping[str, float] | None = None) -> float:
    return compile_expr(src).evaluate(variables)
