```python
import math
import threading
import pytest
import solution
from solution import (
    Expr, ExprError, ExprSyntaxError, ExprNameError, ExprEvalError,
    compile_expr, evaluate,
)

# ─── Type checking ─────────────────────────────────────────────────────────────

class TestTypeChecking:
    def test_non_str_raises_type_error(self):
        for bad in [42, None, b"1+1", ["1"], 3.14]:
            with pytest.raises(TypeError):
                compile_expr(bad)

    def test_str_subclass_ok(self):
        class MyStr(str):
            pass
        e = compile_expr(MyStr("1+1"))
        assert e.evaluate() == 2.0

# ─── Basic arithmetic ──────────────────────────────────────────────────────────

class TestArithmetic:
    @pytest.mark.parametrize("expr,expected", [
        ("1+1", 2.0),
        ("2-3", -1.0),
        ("3*4", 12.0),
        ("10/4", 2.5),
        ("7%3", 1.0),
        ("-7%3", 2.0),
        ("7%-3", -2.0),
        ("2^3", 8.0),
        ("2^0", 1.0),
        ("0^0", 1.0),
        ("42", 42.0),
        ("007", 7.0),
        ("3.25", 3.25),
        ("5.", 5.0),
        (".5", 0.5),
        ("1e3", 1000.0),
        ("1.5E-3", 0.0015),
        (".5e+1", 5.0),
    ])
    def test_basic(self, expr, expected):
        assert evaluate(expr) == pytest.approx(expected)

    def test_all_whitespace_kinds(self):
        assert evaluate("  1\t+\n2\r ") == 3.0

# ─── Precedence and associativity ─────────────────────────────────────────────

class TestPrecedence:
    def test_mul_before_add(self):
        assert evaluate("1+2*3") == 7.0

    def test_add_left_assoc(self):
        assert evaluate("10-3-2") == 5.0

    def test_mul_left_assoc(self):
        assert evaluate("100/5/2") == 10.0

    def test_power_right_assoc(self):
        assert evaluate("2^3^2") == 512.0

    def test_unary_before_power(self):
        assert evaluate("-2^2") == -4.0

    def test_paren_override(self):
        assert evaluate("(-2)^2") == 4.0

    def test_power_negative_exp(self):
        assert evaluate("2^-2") == 0.25

    def test_power_neg_exp_pow(self):
        assert evaluate("2^-1^2") == 0.5

    def test_neg_neg_exp(self):
        assert evaluate("-2^-2") == -0.25

    def test_double_neg(self):
        assert evaluate("--3") == 3.0

    def test_neg_plus_neg(self):
        assert evaluate("-+-3") == 3.0

    def test_mul_neg(self):
        assert evaluate("2*-3") == -6.0

    def test_sub_neg(self):
        assert evaluate("2--3") == 5.0

    def test_cmp_non_assoc(self):
        with pytest.raises(ExprSyntaxError) as ei:
            evaluate("1 < 2 < 3")
        assert ei.value.position == 6

    def test_cmp_eq_neq_non_assoc(self):
        with pytest.raises(ExprSyntaxError):
            evaluate("1 == 2 != 3")

    def test_cmp_in_parens(self):
        assert evaluate("(1 < 2) + 1") == 2.0

    def test_cmp_returns_float(self):
        assert evaluate("1 < 2") == 1.0
        assert evaluate("2 < 1") == 0.0

    def test_cmp_operators(self):
        assert evaluate("1 <= 1") == 1.0
        assert evaluate("1 >= 2") == 0.0
        assert evaluate("1 != 2") == 1.0
        assert evaluate("1 == 1") == 1.0

# ─── Functions ─────────────────────────────────────────────────────────────────

class TestFunctions:
    def test_abs(self):
        assert evaluate("abs(-5)") == 5.0

    def test_sqrt(self):
        assert evaluate("sqrt(9)") == 3.0

    def test_min(self):
        assert evaluate("min(3,1,2)") == 1.0

    def test_max(self):
        assert evaluate("max(3,1,2)") == 3.0

    def test_min_single(self):
        assert evaluate("min(5)") == 5.0

    def test_round_one_arg(self):
        assert evaluate("round(2.5)") == 2.0  # banker's rounding

    def test_round_two_args(self):
        assert evaluate("round(3.14159, 2)") == 3.14

    def test_round_negative_digits(self):
        assert evaluate("round(1234, -2)") == 1200.0

    def test_if_true(self):
        assert evaluate("if(1, 10, 20)") == 10.0

    def test_if_false(self):
        assert evaluate("if(0, 10, 20)") == 20.0

    def test_if_lazy_true_branch(self):
        assert evaluate("if(1, 2, 1/0)") == 2.0

    def test_if_lazy_false_branch(self):
        assert evaluate("if(0, missing, 4)") == 4.0

    def test_if_condition_error(self):
        with pytest.raises(ExprEvalError):
            evaluate("if(1/0, 1, 2)")

    def test_if_takes_branch_error(self):
        with pytest.raises(ExprNameError):
            evaluate("if(1, missing, 2)")

    def test_function_whitespace(self):
        assert evaluate("abs ( - 3 )") == 3.0

    def test_min_max_nested(self):
        assert evaluate("max(min(1,2), min(3,4))") == 3.0

# ─── Variables ─────────────────────────────────────────────────────────────────

class TestVariables:
    def test_variable_lookup(self):
        assert evaluate("x + 1", {"x": 5}) == 6.0

    def test_int_value_converted(self):
        assert evaluate("x * 2", {"x": 3}) == 6.0

    def test_missing_variable(self):
        with pytest.raises(ExprNameError) as ei:
            evaluate("x + 1", {})
        assert ei.value.name == "x"

    def test_none_means_empty(self):
        with pytest.raises(ExprNameError):
            evaluate("x", None)

    def test_extra_keys_ignored(self):
        assert evaluate("x", {"x": 1, "y": 2}) == 1.0

    def test_non_finite_variable(self):
        with pytest.raises(ExprEvalError):
            evaluate("x", {"x": float('inf')})
        with pytest.raises(ExprEvalError):
            evaluate("x", {"x": float('nan')})

    def test_variables_frozenset(self):
        e = compile_expr("x + y * z")
        assert e.variables == frozenset({"x", "y", "z"})

    def test_variables_no_funcs(self):
        e = compile_expr("abs(x) + min(y, z)")
        assert e.variables == frozenset({"x", "y", "z"})

    def test_ident_not_func_is_var(self):
        # "min + 1" → variable named min
        assert evaluate("min + 1", {"min": 10}) == 11.0

    def test_variables_property(self):
        e = compile_expr("a + b + a")
        assert e.variables == frozenset({"a", "b"})

# ─── Compile-time errors ───────────────────────────────────────────────────────

class TestSyntaxErrors:
    @pytest.mark.parametrize("src,pos", [
        ("", 0),
        ("(1+2", 4),
        ("1+2)", 3),
        ("()", 1),
        ("1 < 2 < 3", 6),
        ("max(1,)", 6),
        ("2x", 1),
        ("1..2", 2),
        ("3 + 1e+", 4),
        ("1 = 2", 2),
        ("abs 1", 4),
        ("1 + 2 !", 6),
        ("$1", 0),
        ("1 $ 2", 2),
        ("2**3", 2),
        ("1 + + ", 5),
    ])
    def test_positions(self, src, pos):
        with pytest.raises(ExprSyntaxError) as ei:
            compile_expr(src)
        assert ei.value.position == pos

    def test_unknown_char(self):
        with pytest.raises(ExprSyntaxError):
            compile_expr("1 + é")

    def test_unknown_func(self):
        with pytest.raises(ExprNameError) as ei:
            compile_expr("foo(1)")
        assert ei.value.name == "foo"

    def test_unknown_func_case(self):
        with pytest.raises(ExprNameError) as ei:
            compile_expr("Abs(1)")
        assert ei.value.name == "Abs"

    def test_wrong_arg_count(self):
        with pytest.raises(ExprSyntaxError) as ei:
            compile_expr("1 + round(1,2,3)")
        assert ei.value.position == 4

    def test_wrong_arg_count_min(self):
        with pytest.raises(ExprSyntaxError) as ei:
            compile_expr("abs()")
        assert ei.value.position == 0

    def test_leftmost_func_error(self):
        with pytest.raises(ExprNameError) as ei:
            compile_expr("bar(1) + foo(2)")
        assert ei.value.name == "bar"

    def test_leftmost_arg_count_error(self):
        with pytest.raises(ExprSyntaxError) as ei:
            compile_expr("abs(1,2) + sqrt(1,2)")
        assert ei.value.position == 0

    def test_max_empty_args(self):
        with pytest.raises(ExprSyntaxError) as ei:
            compile_expr("max()")
        assert ei.value.position == 0

    def test_compile_does_not_eval(self):
        e = compile_expr("1/0")
        assert e.source == "1/0"
        with pytest.raises(ExprEvalError):
            e.evaluate()

    def test_compile_does_not_check_names(self):
        e = compile_expr("undefined_var + 1")
        assert e.variables == frozenset({"undefined_var"})

# ─── Evaluation errors ─────────────────────────────────────────────────────────

class TestEvalErrors:
    def test_div_by_zero(self):
        with pytest.raises(ExprEvalError):
            evaluate("1/0")

    def test_mod_by_zero(self):
        with pytest.raises(ExprEvalError):
            evaluate("1%0")

    def test_sqrt_negative(self):
        with pytest.raises(ExprEvalError):
            evaluate("sqrt(-1)")

    def test_zero_neg_power(self):
        with pytest.raises(ExprEvalError):
            evaluate("0^-1")

    def test_neg_base_non_int_exp(self):
        with pytest.raises(ExprEvalError):
            evaluate("(-1)^0.5")

    def test_overflow(self):
        with pytest.raises(ExprEvalError):
            evaluate("10^400")

    def test_mult_overflow(self):
        with pytest.raises(ExprEvalError):
            evaluate("1e308 * 10")

    def test_add_overflow(self):
        with pytest.raises(ExprEvalError):
            evaluate("-1e308 - 1e308")

    def test_round_non_int_digits(self):
        with pytest.raises(ExprEvalError):
            evaluate("round(1.5, 1.5)")

    def test_eval_order_left_to_right(self):
        # u + 1/0: u is undefined → NameError first
        with pytest.raises(ExprNameError):
            evaluate("u + 1/0", {})

    def test_eval_order_right_first(self):
        # 1/0 + u: 1/0 evaluated first → EvalError
        with pytest.raises(ExprEvalError):
            evaluate("1/0 + u", {"u": 1})

# ─── Deep nesting (no RecursionError) ─────────────────────────────────────────

class TestDeepNesting:
    def test_nested_parens(self):
        depth = 100_000
        src = "(" * depth + "1" + ")" * depth
        e = compile_expr(src)
        assert e.evaluate() == 1.0

    def test_chained_unary(self):
        depth = 100_000
        src = "-" * depth + "1"
        e = compile_expr(src)
        assert e.evaluate() == 1.0  # even number of minuses

    def test_chained_unary_odd(self):
        depth = 99_999
        src = "-" * depth + "1"
        e = compile_expr(src)
        assert e.evaluate() == -1.0

    def test_flat_sum(self):
        n = 100_000
        src = "+".join(["1"] * n)
        e = compile_expr(src)
        assert e.evaluate() == float(n)

    def test_nested_if(self):
        depth = 5000
        src = "if(1, " * depth + "42" + ", 0)" * depth
        e = compile_expr(src)
        assert e.evaluate() == 42.0

    def test_nested_functions(self):
        depth = 5000
        src = "abs(" * depth + "-42" + ")" * depth
        e = compile_expr(src)
        assert e.evaluate() == 42.0

    def test_low_recursion_limit(self):
        import sys
        old = sys.getrecursionlimit()
        try:
            sys.setrecursionlimit(50)
            src = "(" * 500 + "1" + ")" * 500
            e = compile_expr(src)
            assert e.evaluate() == 1.0
        finally:
            sys.setrecursionlimit(old)

