# ─── Immutability and thread safety ───────────────────────────────────────────

class TestImmutability:
    def test_cannot_set_attr(self):
        e = compile_expr("1+1")
        with pytest.raises(AttributeError):
            e.source = "x"
        with pytest.raises(AttributeError):
            e.variables = frozenset()

    def test_thread_safety(self):
        e = compile_expr("x * x + 1")
        results = []
        errors = []

        def worker(val):
            try:
                for _ in range(1000):
                    r = e.evaluate({"x": val})
                    results.append(r)
            except Exception as ex:
                errors.append(ex)

        threads = [threading.Thread(target=worker, args=(i,)) for i in range(8)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        assert not errors
        assert all(r == i * i + 1 for i, r in zip(
            [x for x in range(8) for _ in range(1000)], results))

