class TestEdgeCases:
    def test_source_attribute(self):
        src = "  x + 1  "
        e = compile_expr(src)
        assert e.source == src

    def test_evaluate_returns_float(self):
        r = evaluate("1 + 1")
        assert isinstance(r, float)

    def test_comparison_returns_float(self):
