        assert isinstance(r, float)
        assert r == 1.0

    def test_nested_cmp_in_parens(self):
        assert evaluate("(1 < 2) < 3") == 1.0  # 1.0 < 3 → True → 1.0

    def test_cmp_in_func_arg(self):
        assert evaluate("abs(if(1 < 2, -5, 5))") == 5.0

    def test_variable_named_if(self):
        assert evaluate("if + 1", {"if": 10}) == 11.0

    def test_variable_named_abs(self):
        assert evaluate("abs + 1", {"abs": 3}) == 4.0

    def test_infinite_number(self):
        with pytest.raises(ExprSyntaxError):
            compile_expr("1e999")

    def test_number_followed_by_ident(self):
        with pytest.raises(ExprSyntaxError) as ei:
            compile_expr("2x")
        assert ei.value.position == 1

    def test_1e_is_malformed(self):
        with pytest.raises(ExprSyntaxError) as ei:
            compile_expr("1e")
        assert ei.value.position == 0

    def test_expr_error_hierarchy(self):
        assert issubclass(ExprSyntaxError, ExprError)
        assert issubclass(ExprNameError, ExprError)
        assert issubclass(ExprEvalError, ExprError)

    def test_complex_formula(self):
        # from the problem statement
        e = compile_expr("if(qty >= 10, price * 0.9, price) * qty")
        assert e.evaluate({"qty": 15, "price": 100}) == pytest.approx(1350.0)
        assert e.evaluate({"qty": 5, "price": 100}) == pytest.approx(500.0)

    def test_mapping_interface(self):
        from collections import OrderedDict
        e = compile_expr("a + b")
        assert e.evaluate(OrderedDict([("a", 1), ("b", 2)])) == 3.0

    def test_round_bankers(self):
        assert evaluate("round(0.5)") == 0.0
        assert evaluate("round(1.5)") == 2.0
        assert evaluate("round(2.5)") == 2.0
        assert evaluate("round(3.5)") == 4.0
